using System;using System.Collections.Generic;using System.Linq;using UnityEngine;
namespace ROM.Progression {
[Serializable]public sealed class RiftRepairQuote {public int Missing,Cost;public string[] Ids;}
public sealed partial class JournalState {
 public int StarterAxeDurabilityVersion,StarterAxeDurability,StarterAxeMaximumDurability;
 public int StarterDurabilityNow=>StarterAxeDurabilityVersion>0?Mathf.Clamp(StarterAxeDurability,0,Mathf.Max(1,StarterAxeMaximumDurability)):RiftRepairTuning.Load.Maximum;
 public int StarterDurabilityMax=>StarterAxeDurabilityVersion>0?Mathf.Max(1,StarterAxeMaximumDurability):RiftRepairTuning.Load.Maximum;
 public bool EnsureDurability(){var tuning=RiftRepairTuning.Load;if(!tuning)return false;bool changed=false;if(StarterAxeDurabilityVersion<=0){StarterAxeDurabilityVersion=1;StarterAxeMaximumDurability=tuning.Maximum;StarterAxeDurability=StarterAxeMaximumDurability;changed=true;}else{int maximum=Mathf.Clamp(StarterAxeMaximumDurability,1,10000),value=Mathf.Clamp(StarterAxeDurability,0,maximum);if(StarterAxeMaximumDurability!=maximum||StarterAxeDurability!=value){StarterAxeMaximumDurability=maximum;StarterAxeDurability=value;changed=true;}}if(LootAxes==null)LootAxes=new List<RiftLootAxe>();foreach(var item in LootAxes.Where(x=>x!=null)){if(item.DurabilityVersion<=0){item.DurabilityVersion=1;item.MaximumDurability=tuning.Maximum;item.Durability=item.MaximumDurability;changed=true;}else{int max=Mathf.Clamp(item.MaximumDurability,1,10000),value=Mathf.Clamp(item.Durability,0,max);if(item.MaximumDurability!=max||item.Durability!=value){item.MaximumDurability=max;item.Durability=value;changed=true;}}}return changed;}
 public RiftRepairQuote RepairQuote(string id,bool all){var tuning=RiftRepairTuning.Load;if(!tuning)return null;var ids=new List<string>();long missing=0;if(all||id=="starter:axe"){ids.Add("starter:axe");missing+=StarterDurabilityMax-StarterDurabilityNow;}if(LootAxes!=null)foreach(var item in LootAxes){if(item==null||string.IsNullOrEmpty(item.Id)||item.Id=="starter:axe"||LootAxes.Count(x=>x!=null&&x.Id==item.Id)!=1)return null;if(all||item.Id==id){ids.Add(item.Id);missing+=item.DurabilityMax-item.DurabilityNow;}}if(ids.Count==0)return null;int points=(int)Math.Min(int.MaxValue,missing);return new RiftRepairQuote{Missing=points,Cost=tuning.Price(points),Ids=ids.ToArray()};}
 public void RestoreDurability(RiftRepairQuote quote){EnsureDurability();foreach(string id in quote.Ids){if(id=="starter:axe")StarterAxeDurability=StarterAxeMaximumDurability;else{var item=LootAxes.Single(x=>x.Id==id);item.Durability=item.MaximumDurability;}}}
}
}
